from pathlib import Path
import json,copy,hashlib
P=Path(__file__).parent
path=P/'additions.json';xs=json.loads(path.read_text());idx={x['card']['id']:x for x in xs};fixes=[]
def fix(n,q,d,r,issue,p=None,warning=None):
 i=f'exp26-care-{n:04d}';before=copy.deepcopy(idx[i]);after=copy.deepcopy(before);c=after['card'];c['question']=q;after['reason']=r
 if c['level']>=3:c['detail']['text']='仮の場面です。'+d
 if p:c['perspective']=p
 if warning:c['content_warning']=warning
 fixes.append({'id':i,'priority':'required','issue':issue,'before':before,'after':after,'status':'draft_unapplied'})
fix(23,'家事の回数は同じでも、一方はいつ来るか分からない用事が多い。担当を決める時、回数と自由な時間の見通しをどう考える？','','実作業と段取りの評価ではなく、同じ回数でも時間を中断する頻度が違う時の公平を聞く。','0021の実作業と段取りの評価を洗濯へ置き換えた重複に見える。')
fix(155,'あなたは家族のケア予定を組み直すたび自分の休みを削っている。本人はその日になって希望を決めたいと言う。自分が支え続けることと本人の自由を、どんな形で守りたい？','本人の生活の裁量と、調整を担う自分が休める条件が競合します。今の方法を続けられるとは決まっていません。','希望変更の手順一般から、自分が支え続ける時間と本人の裁量の葛藤へ。','通常のケア予定の調整だけではL4の本人の利害が弱い。')
fix(182,'あなたは家族を見送り、長い介護の終わりにほっとしている。別の家族は楽しげな話をすることに抵抗がある。皆を集めるなら、安堵と喪失をどんな時間として扱いたい？','介護を終えた安堵と家族を失った悲しみが同時にあります。家族の感じ方を一つにそろえる必要はありません。','企画の形式を選ぶ問から、同じ喪失に異なる感情を持つ自分と家族の時間へ。','集まりの企画を選ぶだけでは本人の喪失や関係の意味が弱い。')
fix(189,'あなたは離婚後も、家族が元配偶者を大切な一員と感じていると知る。次の家族の集まりを任された時、自分の居場所と続く相手の関係をどう考える？','安全の懸念や深刻な対立はなくても、別れた関係の終わり方は家族で異なる設定です。自分の所属の安心も含めます。','招待範囲の一般論から、自分の離婚後の所属と他の家族の関係の継続へ。','主催者の通常の招待の調整だけではL4の関係の意味が弱い。')
fix(197,'あなたは老後も成人した子の近くで暮らすつもりだったが、子は遠くで暮らすと決めた。家族がそばにいる未来を失う気持ちと、自分の暮らしを選び直すことをどう受け止める？','子の独立が家族関係の終了とは限りません。思い描いた未来を失う本人の感情と、自分の生活を作り直す選択が並びます。','予定を組む段階から、老後の家族像を失う本人の意味と選び直しへ。','子抜きの予定を組む手順では本人の人生の意味が不足する。',p='affected')
fix(246,'あなたは将来の世話を家族へ託すため自分の希望を残す。まだ決められない部分があり、残さないと家族が判断を背負う。何を今の約束にし、何を迷いとして残したい？','自分の将来を固定しない望みと、家族に判断を託す責任が並びます。記録の法律上の効力は扱いません。','記録の編集一般から、自分の将来と家族へ託す判断の責任へ。','希望の記録に迷いを残す編集だけではL4の責任が弱い。')
fix(253,'あなたは家族の一人が違う価値観を語らなくなるのを見た。自分も昔、居場所を失う怖さから考えを隠していた。今の家族の穏やかさを何として受け止める？','表面の一致と安心して違いを語れることが同じとは限りません。自分の過去を重ねて見る第三者の立場です。','一般的な第三者の希望から、自分も所属のため沈黙した過去と今の家族の意味へ。','眺める立場だけではL4の本人への深い置換が弱い。',warning=['family_conflict'])
